    // unscaled, themed tiers say so instead, since they aren't backed by a token.
    const propertyDocs = bp
      .map(([names, w]) => {
        const short = names[0];
        const source = canonicalScaleNames.has(short)
          ? `mirrors \`--instui-breakpoints-${short}\``
          : short === "xs"
